cat > /tmp/sim.py <<'E'
import sys
L=[l.split(';')[0].strip() for l in open('prog.pw9')]
P=[l.split() for l in L if l]
R=dict(a=0,b=0,c=0,d=0)
v=lambda x:R[x] if x in R else int(x)
i=0;n=0;s=0
while 0<=i<len(P):
    p=P[i];o=p[0];n+=1;j=1
    if o=='set':R[p[1]]=v(p[2])%65536
    elif o=='add':R[p[1]]=(R[p[1]]+v(p[2]))%65536
    elif o=='mul':R[p[1]]=(R[p[1]]*v(p[2]))%65536
    elif o=='mod':
        if v(p[2])>0:R[p[1]]%=v(p[2])
    elif o=='dec':R[p[1]]=max(0,R[p[1]]-1)
    elif o=='jnz':
        if v(p[1])!=0:j=v(p[2])
    elif o=='skp':
        if v(p[1])<v(p[2]):j=2
    elif o=='out':s+=v(p[1])
    else:raise Exception(p)
    i+=j
print(s,n)
open('answer.txt','w').write(f"{s} {n}\n")
E
python3 -I /tmp/sim.py; cat answer.txt
